// CHỐT 1 — Chuẩn hoá và làm sạch đầu vào.
// Mọi thứ đến từ bên ngoài đều là DỮ LIỆU KHÔNG TIN CẬY.
// Ta không bao giờ ghép thẳng vào prompt mà không bọc thẻ <untrusted>,
// và KHÔNG BAO GIỜ ghép vào lệnh shell — workflow này không có node nào chạy shell.
const body = $input.first().json.body ?? $input.first().json;

const clean = (s, max) => String(s ?? '')
  .replace(/\u0000/g, '')
  .slice(0, max);

const profile = clean(body.profile, 40) || 'engineering';
const request = clean(body.request, 8000);

// Quyết định định tuyến làm ở ĐÂY, bằng JS thuần — không phải trong tham số
// của node Switch. Lý do: node đồ hoạ có schema đổi theo từng phiên bản công
// cụ (typeVersion) và việc so sánh kiểu do đó không ổn định giữa các bản n8n;
// một hàm JS trả về đúng MỘT chuỗi thì luôn so sánh bằng '===' được, ở bất kỳ
// phiên bản n8n nào. Node Switch phía sau chỉ đọc `category`, không tự quyết.
const URGENT_RE = /(deploy|rollback|sự cố|incident|production down)/i;
const category = URGENT_RE.test(request) ? 'van-hanh'
  : profile === 'engineering' ? 'ky-thuat'
  : 'phong-ban-khac';

return [{
  json: {
    requestId: `REQ-${Date.now().toString(36).toUpperCase()}`,
    profile,
    requester: clean(body.requester, 80),
    request,
    repo:      clean(body.repo, 200),
    priority:  ['low','normal','high','urgent'].includes(body.priority) ? body.priority : 'normal',
    receivedAt: new Date().toISOString(),
    category,
  }
}];

// Ghi nhật ký kiểm toán cho MỌI yêu cầu — kể cả yêu cầu bị từ chối.
// Nhật ký này là thứ duy nhất trả lời được câu hỏi
// "tháng trước ai đã bảo agent làm gì" khi có kiểm toán.
const src = $('Chuẩn hoá đầu vào').item.json;
return [{ json: {
  ts: new Date().toISOString(),
  requestId: src.requestId,
  requester: src.requester,
  profile: src.profile,
  route: $runIndex,
  outcome: 'dispatched',
} }];
